public class Main {
    static int init(String label) { System.out.println("    " + label); return 1; }

    static class Parent {
        static int pf = init("Parent.static.field");
        static { init("Parent.static.block"); }
        int i1 = init("Parent.instance.field");
        { init("Parent.instance.block"); }
        Parent() { init("Parent.<init>"); }
    }
    static class Child extends Parent {
        static int cf = init("Child.static.field");
        static { init("Child.static.block"); }
        int i2 = init("Child.instance.field");
        { init("Child.instance.block"); }
        Child() { init("Child.<init>"); }
    }
    static class Const {
        static final int C = 42;                       // 编译期常量 -> 不触发 <clinit>
        static { System.out.println("    Const.<clinit> RUNS (unexpected!)"); }
    }

    public static void main(String[] args) {
        System.out.println("=== 1st new Child() ===");
        new Child();
        System.out.println("=== 2nd new Child() : statics run only once ===");
        new Child();
        System.out.println("=== compile-time constant access ===");
        System.out.println("    Const.C = " + Const.C + "  (no <clinit> line above => constant folded)");
    }
}
